  // f_i <= p[3i-1] na ordem decrescente; a gulosa atinge esse limite.
  prices.sort((a, b) => b - a);

  let total = 0;
  for (let i = 0; i < n; i++) total += prices[i];
  for (let i = 2; i < n; i += 3) total -= prices[i];

  console.log(total);
